-- =========================================================
-- DADOS FICTÍCIOS PARA TESTE - SISTEMA DE VIATURAS ROTAM
-- Total: 200 registros
-- Motos: prefixo 44 + ano + sequência
-- Viaturas 4 rodas: prefixo 55 + sequência iniciando em 4500
-- Observação: placas, KM, cartões e situações são fictícios.
-- =========================================================

USE cadastro_viatura_rotam;

-- Caso queira limpar a tabela antes de inserir, execute manualmente:
-- DELETE FROM viaturas;
-- ALTER TABLE viaturas AUTO_INCREMENT = 1;


-- Conferência rápida
SELECT COUNT(*) AS total_viaturas FROM viaturas;
SELECT ano_modelo, modelo_vtr, marca_vtr, COUNT(*) AS quantidade FROM viaturas GROUP BY ano_modelo, modelo_vtr, marca_vtr ORDER BY ano_modelo, modelo_vtr;